def write(guide):
    used = set()
    for s in guide['sections']:
        used.update(s.get('src', []))
    for u in used:
        assert u in SRC, (guide['key'], u)
    guide['sources'] = [SRC[u] for u in SRC if u in used]
    guide['updated'] = ACC
    with open(os.path.join(OUT, guide['key'] + '.json'), 'w') as fh:
        json.dump(guide, fh, indent=1, ensure_ascii=False)
        fh.write('\n')


