def link_items(guides):
    cat = json.load(open(os.path.join(SITE, 'data/meals/catalog.json')))['items']
    for g in guides:
        ids = list(g['items'])
        for it in cat:
            if any(ref.split('#')[0] == g['key'] for ref in it['guides']) and it['id'] not in ids:
                ids.append(it['id'])
        g['items'] = ids


if __name__ == '__main__':
    os.makedirs(OUT, exist_ok=True)
    link_items((FATS, CINNAMON, DIFF, CHECK, SAFETY))
    for g in (FATS, CINNAMON, DIFF, CHECK, SAFETY):
        write(g)
    print('guides written:', ', '.join(g['key'] for g in (FATS, CINNAMON, DIFF, CHECK, SAFETY)))
